  function entryAccounts(){const list=orderedAccounts();if(!editId)return list;const row=transactions.find(x=>x.id===editId);if(!row)return list;const ids=row.kind==='transfer'?[row.fromAccountId,row.toAccountId]:[row.accountId];for(const id of ids){const account=accounts.find(a=>a.id===id);if(account&&!list.some(a=>a.id===id))list.push(account)}return list.sort((a,b)=>(Number(a.sortOrder)||0)-(Number(b.sortOrder)||0)||(a.id==='cash'?-1:b.id==='cash'?1:a.name.localeCompare(b.name)))}
  function accountFieldMarkup(){const available=entryAccounts(),current=available.some(a=>a.id===selectedAccountId)?selectedAccountId:(available.find(a=>a.id==='cash')?.id||available[0]?.id||'');return `<div class="subfield"><div class="field-label">${T.account} <span>*</span></div><div class="chip-list" data-chip-group="account">${available.map(a=>`<button type="button" class="chip account-picker-chip${a.id===current?' selected':''}" data-value="${esc(a.id)}">${esc(a.name)}${a.archived?` · ${esc(T.accountArchived)}`:''} <small>${T.available} ${rupees(Math.max(0,accountBalance(a.id)))}</small></button>`).join('')}</div></div>`}
