  function investmentNameMarkup(){const names=[...new Set([...transactions.map(x=>x.investmentName),...investmentLedgerEntries.map(x=>x.name)].filter(Boolean))];return `<div class="subfield"><label class="field-label" for="investmentName">${T.investmentName} <span>*</span></label><div class="investment-name-row"><input class="text-input" id="investmentName" list="investmentNameOptions" maxlength="80" placeholder="${T.investmentNamePlaceholder}" value="${esc(investmentNameInput)}"><datalist id="investmentNameOptions">${names.map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist><button type="button" class="small-add-button" data-add-investment-name>${T.addNew}</button></div></div>`}
