  async function removeActivePerson(){const person=people.find(x=>x.id===activePersonId);if(!person||personHasReferences(person.id))return;if(!confirm(T.deletePersonConfirm))return;await LedgerDB.deletePerson(person.id);people=await LedgerDB.people();activePersonId=null;$('#personDetailView').hidden=true;$('#outstandingListView').hidden=false;refresh()}
    async function settlePerson(){const person=people.find(x=>x.id===activePersonId);if(!person)return;const net=outstanding(person.id);if(net===0)return;if(!confirm(T.settleConfirm))return;const type=net>0?'Udhar Received Back':'Udhar Repaid',value={id:crypto.randomUUID(),kind:net>0?'credit':'debit',type,amount:Math.abs(net),date:todayISO(),note:'',category:'',paymentMethod:'',investmentKind:'',person:{id:person.id,name:person.name},source:'',accountId:accounts.find(a=>a.kind==='cash'||a.id==='cash')?.id||accounts[0]?.id||null,createdAt:new Date().toISOString()};const checked=window.PocketLedgerAccountBalances.validateChange(accounts,transactions,{upsert:value});if(!checked.ok){alert(accountHistoryError(checked));return}await LedgerDB.saveTransaction(value);transactions=await LedgerDB.transactions();refresh()}async function copyText(text){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return}const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const copied=document.execCommand('copy');area.remove();if(!copied)throw new Error('copy failed')}
  async function sharePersonSummary(){const person=people.find(x=>x.id===activePersonId);if(!person)return;const net=outstanding(person.id),date=new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}),amount=rupees(Math.abs(net));const text=T.shareText.replace('{name}',person.name).replace('{amount}',amount).replace('{date}',date);try{if(navigator.share)await navigator.share({text});else{await copyText(text);showToast(T.copied)}}catch(error){if(error.name==='AbortError')return;try{await copyText(text);showToast(T.copied)}catch{showToast(T.unableToCopy)}}}
