  async function fallbackReminderShare(person,message){try{if(navigator.share)await navigator.share({text:message});else{await copyText(message);showToast(T.copied)}await markPersonReminded(person)}catch(error){if(error.name==='AbortError')return;try{await copyText(message);showToast(T.copied);await markPersonReminded(person)}catch{showToast(T.unableToCopy)}}}
