  async function savePersonDetails(){const person=people.find(x=>x.id===activePersonId);if(!person)return;person.phone=$('#personPhone').value.trim();person.creditLimit=Math.max(0,Number($('#personCreditLimit').value)||0);await LedgerDB.savePerson(person);people=await LedgerDB.people();renderPersonDetail();showToast(T.personDetailsSaved)}
    function statementHtml(statement){const account=statement.rows.some(row=>row.credit!==undefined),shown=value=>account?Math.max(0,value):value,rows=statement.rows.map(row=>`<tr><td>${esc(row.date)}</td><td>${esc(row.type)}${row.note?` · ${esc(row.note)}`:''}</td><td>${row.amount!==undefined?rupees(row.amount):`${rupees(row.credit)} / ${rupees(row.debit)}`}</td><td>${rupees(shown(row.balance))}</td></tr>`).join('');return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(statement.title)} · ${esc(T.statement)}</title><style>body{font:14px system-ui,sans-serif;color:#17212b;margin:32px}h1{font-size:24px}p{color:#52606d}.summary{display:flex;gap:32px;margin:24px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #d8dee5}th{background:#f1f4f7}@media print{body{margin:12mm}}</style></head><body><h1>${esc(statement.title)} · ${esc(T.statement)}</h1><p>${esc(T.generated)}: ${esc(new Date(statement.generatedAt).toLocaleString())}</p><div class="summary"><strong>${esc(T.openingBalance)}: ${rupees(shown(statement.opening))}</strong><strong>${esc(T.finalBalance)}: ${rupees(shown(statement.final))}</strong></div><table><thead><tr><th>${esc(T.date)}</th><th>${esc(T.description)}</th><th>${esc(T.amount)}</th><th>${esc(T.runningBalance)}</th></tr></thead><tbody>${rows}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`}async function shareStatement(statement){const isAccount=statement.rows.some(row=>row.credit!==undefined),safe=isAccount?{...statement,opening:Math.max(0,statement.opening),final:Math.max(0,statement.final),rows:statement.rows.map(row=>({...row,balance:Math.max(0,row.balance)}))}:statement;const text=PocketLedgerStatements.toText(safe,{generated:T.generated,opening:T.openingBalance,final:T.finalBalance,balance:T.balance});try{if(navigator.share)await navigator.share({title:statement.title,text});else{await copyText(text);showToast(T.copied)}}catch(error){if(error.name!=='AbortError'){await copyText(text);showToast(T.copied)}}}
  function printStatement(statement){const win=window.open('','_blank');if(!win){showToast(T.popupBlocked);return}win.document.open();win.document.write(statementHtml(statement));win.document.close()}
  function localizeStatement(statement){return {...statement,generatedAt:new Date(statement.generatedAt).toLocaleString(language==='gu'?'gu-IN':'en-IN'),rows:statement.rows.map(row=>({...row,date:dateLabel(row.date,{day:'numeric',month:'short',year:'numeric'}),type:displayType(row.type)}))}}
  function personStatement(){const person=people.find(x=>x.id===activePersonId);if(person)return localizeStatement(PocketLedgerStatements.personStatement(person,transactions))}
  function accountStatement(accountId){const account=accounts.find(x=>x.id===accountId);if(account)return localizeStatement(PocketLedgerStatements.accountStatement(account,transactions))}
