  async function useAssistantQuickAdd(){if(!PocketLedgerExperimentalAssistant.available())return;const suggestion=await PocketLedgerExperimentalAssistant.parseForReview($('#quickAddInput').value);if(!suggestion)return;const parsed={...quickParsed,amount:suggestion.amount,amounts:[suggestion.amount],kind:suggestion.kind,type:suggestion.type||quickParsed.type,note:suggestion.note||quickParsed.note,confidence:Math.max(quickParsed.confidence,.6),question:''};renderQuickAddPreview(parsed)}
  function quickEntryForPerson(type){const person=people.find(x=>x.id===activePersonId);if(!person)return;returnToOutstandingDetail=true;const targetKind=(type==='Udhar Given'||type==='Udhar Repaid')?'debit':'credit';showScreen('entry');resetForm();setKind(targetKind);selectedType=type;renderTypeChips();document.querySelectorAll('#typeChips .chip').forEach(c=>c.classList.toggle('selected',c.textContent===displayType(type)));renderDynamicFields();choosePerson(person);$('#amount').focus()}
