  function updateOutstandingHint(){const hint=$('#outstandingHint');if(!hint)return;const who=selectedPerson;if(!who){hint.textContent='';return}let net=outstanding(who.id,editId);let text='',cls='settled';if(selectedType==='Udhar Given'||selectedType==='Udhar Received Back'){if(net>0){text=`${who.name}: ${T.willReceive} ${rupees(net)}`;cls='positive'}else if(net<0){text=`${who.name}: ${T.youOwe} ${rupees(Math.abs(net))}`;cls='negative'}else text=`${who.name}: ${T.settled}`}else{if(net<0){text=`${who.name}: ${T.haveToGive} ${rupees(Math.abs(net))}`;cls='negative'}else if(net>0){text=`${who.name}: ${T.owesYou} ${rupees(net)}`;cls='positive'}else text=`${who.name}: ${T.settled}`}const entered=Number($('#amount')?.value?.replace(/,/g,'')||0),limit=Number(who.creditLimit)||0;if(selectedType==='Udhar Given'&&limit>0&&net+entered>limit){text+=` · ${T.creditLimitExceeded.replace('{limit}',rupees(limit))}`;cls='negative'}hint.textContent=text;hint.className=`outstanding-hint ${cls}`}
