  async function saveExistingInvestment(event){event.preventDefault();const name=$('#existingInvestmentName').value.trim(),cost=Number($('#existingInvestmentAmount').value),rawValue=$('#existingInvestmentValue').value,value=rawValue===''?null:Number(rawValue),date=$('#existingInvestmentDate').value||'',note=$('#existingInvestmentNote').value.trim();if(!name||!Number.isFinite(cost)||cost<=0||value!==null&&(!Number.isFinite(value)||value<0)){$('#existingInvestmentError').textContent=T.existingInvestmentInvalid;return}const now=new Date().toISOString(),holding={id:crypto.randomUUID(),type:'holding',name,kind:$('#existingInvestmentKind').value,amount:cost,date,note,createdAt:now};await LedgerDB.saveInvestmentRecord(holding);if(value!==null)await LedgerDB.saveInvestmentRecord({id:crypto.randomUUID(),type:'snapshot',name,kind:holding.kind,value,date:todayISO(),note,createdAt:now});investmentLedgerEntries=await LedgerDB.investmentRecords();$('#existingInvestmentDialog').close();refresh();if(currentScreen==='investments')renderInvestmentScreen();showToast(T.existingInvestmentSaved)}
  function populateInvestmentSale(editRow=null){const records=investmentRecords(),select=$('#investmentSaleName'),previous=editRow?.investmentName||activeInvestmentName||select.value;select.innerHTML=records.map(row=>'<option value="'+esc(row.name)+'">'+esc(row.name)+' · '+esc(rupees(row.remainingCost))+'</option>').join('');if(records.some(row=>row.name===previous))select.value=previous;select.disabled=!!editRow;const account=$('#investmentSaleAccount'),selected=editRow?.accountId||selectedAccountId;account.innerHTML=orderedAccounts().map(row=>'<option value="'+esc(row.id)+'">'+esc(row.name)+' · '+T.available+' '+rupees(Math.max(0,accountBalance(row.id)))+'</option>').join('');if(accounts.some(row=>row.id===selected&&!row.archived))account.value=selected;$('#investmentSaleDate').value=editRow?.date||todayISO();$('#investmentSaleReceived').value=editRow?editRow.amount:'';$('#investmentSaleCost').value=editRow?.redeemedCost??'';$('#investmentSaleNote').value=editRow?.note||'';$('#investmentSaleForm').dataset.editId=editRow?.id||'';investmentSaleSelectionChanged()}
  function investmentSaleSelectionChanged(){const record=investmentRecords().find(row=>row.name===$('#investmentSaleName').value),remaining=record?.remainingCost||0;$('#investmentSaleRemaining').textContent=T.remainingCost+': '+rupees(remaining);const editRow=transactions.find(row=>row.id===$('#investmentSaleForm').dataset.editId),availableCost=remaining+(editRow?Number(editRow.redeemedCost)||0:0),receivedText=$('#investmentSaleReceived').value,received=Number(receivedText),redeemed=Number($('#investmentSaleCost').value);let preview='',error='';if(!receivedText)error=T.investmentSaleInvalid;else if(!Number.isFinite(redeemed)||redeemed<0)error=T.investmentSaleInvalid;else if(redeemed>availableCost)error=T.redeemedCostTooHigh.replace('{amount}',rupees(availableCost));else if(!Number.isFinite(received)||received<0)error=T.investmentSaleInvalid;else preview=(received-redeemed>=0?T.profit:T.loss)+' '+rupees(Math.abs(received-redeemed));$('#investmentSaleError').textContent=error;$('#investmentSalePreview').textContent=error?'':preview;$('#investmentSalePreview').className='investment-sale-preview '+((received-redeemed)<0?'negative':'positive');$('#investmentSaleForm button[type=submit]').disabled=!!error}
