  async function saveInvestmentSale(event){event.preventDefault();const editId=$('#investmentSaleForm').dataset.editId||null,name=$('#investmentSaleName').value,record=investmentRecords().find(row=>row.name===name),existing=transactions.find(row=>row.id===editId),received=Number($('#investmentSaleReceived').value),cost=Number($('#investmentSaleCost').value),accountId=$('#investmentSaleAccount').value,date=$('#investmentSaleDate').value,maxCost=(record?.remainingCost||0)+(existing?Number(existing.redeemedCost)||0:0);if(!record||!date||!Number.isFinite(received)||received<0||!Number.isFinite(cost)||cost<0||cost>maxCost){investmentSaleSelectionChanged();return}if(received===0&&cost===0){$('#investmentSaleError').textContent=T.investmentSaleInvalid;return}const value={id:editId||crypto.randomUUID(),createdAt:existing?.createdAt||new Date().toISOString(),kind:received>0?'credit':'noncash',type:'Investment Sale',amount:received,redeemedCost:cost,investmentName:name,investmentKind:record.kind,accountId:received>0?accountId:null,date,note:$('#investmentSaleNote').value.trim(),category:'',person:null};if(received>0&&!accountId){$('#investmentSaleError').textContent=T.accountRequired;return}const checked=window.PocketLedgerAccountBalances.validateChange(accounts,transactions,{upsert:value});if(!checked.ok){$('#investmentSaleError').textContent=accountHistoryError(checked);return}await LedgerDB.saveTransaction(value);transactions=await LedgerDB.transactions();selectedAccountId=accountId||selectedAccountId;investmentNameInput=name;$('#investmentSaleDialog').close();$('#investmentSaleForm').dataset.editId='';activeInvestmentName=name;refresh();showScreen('investments');showToast(T.saleSaved)}
