  async function convertInvestmentToExisting(id){const row=transactions.find(x=>x.id===id);if(!row||row.type!=='Investment'||row.kind!=='debit')return;if(!confirm(T.convertInvestmentConfirm.replace('{amount}',rupees(row.amount))))return;const converted={...row,kind:'noncash',type:'Investment Existing',originalType:'Investment',conversionAuditNote:T.convertInvestmentAudit,note:[row.note,T.convertInvestmentAudit].filter(Boolean).join(' · ')};await LedgerDB.saveTransaction(converted);transactions=await LedgerDB.transactions();refresh();renderInvestmentScreen();showToast(T.investmentConverted)}
  function reminderDueDate(x){return String(x.dueDate||'').slice(0,10)}
  function reminderDayDifference(dueDate){const today=new Date(`${todayISO()}T00:00:00`),due=new Date(`${dueDate}T00:00:00`);return Math.round((due-today)/86400000)}
  function reminderPersonName(x){return people.find(p=>p.id===x.person?.id)?.name||x.person?.name||T.person}
  function reminderRelativeDate(x){const days=reminderDayDifference(reminderDueDate(x));if(days===0)return T.today;if(days===1)return T.reminderInOneDay;if(days>1)return T.reminderInDays.replace('{count}',days);if(days===-1)return T.reminderOverdueOneDay;return T.reminderOverdueBy.replace('{count}',Math.abs(days))}
  function renderDashboardReminders(){const pending=reminders.filter(x=>x.status==='Pending'),today=todayISO(),overdue=pending.filter(x=>reminderDueDate(x)<today),upcoming=pending.filter(x=>reminderDueDate(x)>=today).sort((a,b)=>reminderDueDate(a).localeCompare(reminderDueDate(b))||(a.time||'').localeCompare(b.time||'')).slice(0,3);$('#overdueReminderCount').textContent=String(overdue.length);$('#overdueReminderCount').classList.toggle('negative',overdue.length>0);$('#upcomingReminderList').innerHTML=upcoming.map(x=>`<div class="dashboard-reminder-row"><span><strong>${esc(reminderPersonName(x))}</strong><small class="${x.type==='receive'?'positive':'negative'}">${x.type==='receive'?T.toReceive:T.toGive} · ${rupees(x.amount)}</small></span><small>${esc(dateLabel(reminderDueDate(x)))} · ${esc(reminderRelativeDate(x))}</small></div>`).join('')||`<p class="dashboard-empty-line">${esc(T.noUpcomingReminders)}</p>`}
  function renderReminderBanner(){if(!$('#reminderBanner'))return;const pending=reminders.filter(x=>x.status==='Pending'),today=todayISO(),dueToday=pending.filter(x=>reminderDueDate(x)===today).length,overdue=pending.filter(x=>reminderDueDate(x)<today).length;$('#reminderBanner').hidden=dueToday+overdue===0;if(!$('#reminderBanner').hidden)$('#reminderBannerText').textContent=T.reminderBannerText.replace('{today}',dueToday).replace('{overdue}',overdue)}
  function renderReminderScreen(){const pending=reminders.filter(x=>x.status==='Pending');$('#reminderReceiveTotal').textContent=rupees(pending.filter(x=>x.type==='receive').reduce((s,x)=>s+Number(x.amount||0),0));$('#reminderGiveTotal').textContent=rupees(pending.filter(x=>x.type==='give').reduce((s,x)=>s+Number(x.amount||0),0));document.querySelectorAll('.reminder-tab').forEach(b=>b.classList.toggle('active',b.dataset.reminderTab===reminderTab));let rows=reminders.filter(x=>{const date=reminderDueDate(x);return reminderTab==='Done'?x.status==='Done':x.status==='Pending'&&(reminderTab==='Today'?date===todayISO():reminderTab==='Upcoming'?date>todayISO():date<todayISO())});rows.sort((a,b)=>reminderTab==='Done'?b.dueDate.localeCompare(a.dueDate):a.dueDate.localeCompare(b.dueDate)||(a.time||'').localeCompare(b.time||''));$('#reminderList').innerHTML=rows.map(x=>{const person=reminderPersonName(x),overdue=reminderTab==='Overdue',typeLabel=x.type==='receive'?T.toReceive:T.toGive,relative=x.status==='Done'?T.done:reminderRelativeDate(x);return `<article class="reminder-row ${overdue?'overdue':''}"><div class="reminder-row-main"><strong>${esc(person)}</strong><span class="reminder-type ${x.type==='receive'?'positive':'negative'}">${esc(typeLabel)}</span><small>${esc(dateLabel(reminderDueDate(x),{day:'numeric',month:'short',year:'numeric'}))}${x.time?` · ${esc(x.time)}`:''} · ${esc(relative)}</small>${x.note?`<small class="reminder-note">${esc(x.note)}</small>`:''}</div><strong class="reminder-row-amount ${x.type==='receive'?'positive':'negative'}">${rupees(x.amount)}</strong><div class="reminder-actions">${x.status==='Pending'?`<button type="button" data-reminder-action="done" data-reminder-id="${esc(x.id)}">${T.markDone}</button><button type="button" data-reminder-action="edit" data-reminder-id="${esc(x.id)}">${T.edit}</button><button type="button" data-reminder-action="delete" data-reminder-id="${esc(x.id)}">${T.delete}</button><button type="button" data-reminder-action="calendar" data-reminder-id="${esc(x.id)}">${T.addToCalendar}</button><div class="reminder-snooze">${T.snooze}: <button type="button" data-reminder-action="snooze" data-days="1" data-reminder-id="${esc(x.id)}">${T.tomorrow}</button><button type="button" data-reminder-action="snooze" data-days="3" data-reminder-id="${esc(x.id)}">${T.threeDays}</button><button type="button" data-reminder-action="snooze" data-days="7" data-reminder-id="${esc(x.id)}">${T.nextWeek}</button></div>`:`<span class="reminder-done-label">${T.done}</span>`}</div></article>`}).join('');$('#reminderEmpty').hidden=rows.length>0;$('#reminderEmpty').textContent=T[`empty${reminderTab}`]||T.noReminders;$('#reminderList').querySelectorAll('[data-reminder-action]').forEach(button=>button.addEventListener('click',()=>handleReminderAction(button.dataset.reminderAction,button.dataset.reminderId,Number(button.dataset.days)||0)));renderReminderBanner()}
  function fillReminderPeople(selectedId=''){const select=$('#reminderPerson');select.innerHTML=`<option value="">${esc(T.choosePerson)}</option>`+people.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');select.value=selectedId}
  function openReminderForm({reminder=null,personId='',amount='',type='receive'}={}){reminderEditId=reminder?.id||null;$('#reminderForm').hidden=false;$('#reminderList').hidden=true;$('#reminderEmpty').hidden=true;$('#addReminderButton').hidden=true;$('#reminderFormTitle').textContent=reminder?T.editReminder:T.addReminder;fillReminderPeople(reminder?.person?.id||personId);$('#reminderType').value=reminder?.type||type;$('#reminderAmount').value=reminder?formatMoney(reminder.amount):amount?formatMoney(amount):'';$('#reminderDueDate').value=reminder?.dueDate||todayISO();$('#reminderTime').value=reminder?.time||'';$('#reminderNote').value=reminder?.note||'';$('#reminderRepeat').value=reminder?.repeat||'None';$('#reminderStatus').value=reminder?.status||'Pending';$('#reminderFormError').textContent='';$('#reminderForm').scrollIntoView({behavior:'smooth',block:'start'})}
  function closeReminderForm(){reminderEditId=null;$('#reminderForm').hidden=true;$('#reminderList').hidden=false;$('#addReminderButton').hidden=false;$('#reminderForm').reset();renderReminderScreen()}
  function reminderDaysFrom(date,count){const d=new Date(`${date}T00:00:00`);d.setDate(d.getDate()+count);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  function nextRepeatDate(reminder){const d=new Date(`${reminder.dueDate}T00:00:00`);if(reminder.repeat==='Weekly')d.setDate(d.getDate()+7);else if(reminder.repeat==='Monthly'){const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
  async function markReminderDone(reminder,shouldRefresh=true){reminder.status='Done';await LedgerDB.saveReminder(reminder);if(reminder.repeat&&reminder.repeat!=='None'){let dueDate=nextRepeatDate(reminder);while(dueDate<=todayISO())dueDate=reminder.repeat==='Weekly'?reminderDaysFrom(dueDate,7):nextRepeatDate({...reminder,dueDate});await LedgerDB.saveReminder({...reminder,id:crypto.randomUUID(),dueDate,status:'Pending',createdAt:new Date().toISOString()})}reminders=await LedgerDB.reminders();if(shouldRefresh)refresh()}
  async function handleReminderAction(action,id,days){const reminder=reminders.find(x=>x.id===id);if(!reminder)return;if(action==='done'){if(confirm(T.recordPayment)){pendingReminderPaymentId=id;startReminderPayment(reminder)}else await markReminderDone(reminder)}else if(action==='edit')openReminderForm({reminder});else if(action==='delete'){if(!confirm(T.deleteReminderConfirm))return;await LedgerDB.deleteReminder(id);reminders=await LedgerDB.reminders();refresh()}else if(action==='snooze'){reminder.dueDate=reminderDaysFrom(todayISO(),days);await LedgerDB.saveReminder(reminder);reminders=await LedgerDB.reminders();refresh()}else if(action==='calendar')downloadReminderCalendar(reminder)}
  function startReminderPayment(reminder){returnToOutstandingDetail=false;showScreen('entry');resetForm();const type=reminder.type==='receive'?'Udhar Received Back':'Udhar Repaid',targetKind=reminder.type==='receive'?'credit':'debit',person=people.find(p=>p.id===reminder.person?.id)||reminder.person;setKind(targetKind);selectedType=type;renderTypeChips();document.querySelectorAll('#typeChips .chip').forEach(c=>c.classList.toggle('selected',c.textContent===displayType(type)));renderDynamicFields();if(person)choosePerson(person);$('#amount').value=formatMoney(reminder.amount);$('#note').value=reminder.note||''}
  async function requestReminderNotificationPermission(){if(localStorage.getItem('pocket-ledger-notification-asked'))return;localStorage.setItem('pocket-ledger-notification-asked','1');if(!('Notification'in window))return;if(Notification.permission!=='default')return;if(!confirm(T.notificationPermissionExplain))return;try{await Notification.requestPermission()}catch{}}
  async function createReminderNotification(reminder){if(!('Notification'in window)||Notification.permission!=='granted'||!('serviceWorker'in navigator))return;const body=T.notificationReminderBody.replace('{type}',reminder.type==='receive'?T.toReceive:T.toGive).replace('{person}',reminderPersonName(reminder)).replace('{amount}',rupees(reminder.amount));try{const registration=await navigator.serviceWorker.ready;await registration.showNotification(T.notificationReminderTitle,{body,tag:`pocket-ledger-${reminder.id}-${reminder.dueDate}-${reminder.time||''}`,data:{url:'./'}})}catch{}}
  async function checkDueReminders(){const due=reminders.filter(x=>x.status==='Pending'&&reminderDueTimestamp(x)<=Date.now());if(!due.length)return;let notified=[];try{notified=JSON.parse(localStorage.getItem('pocket-ledger-notified-reminders')||'[]')}catch{}let changed=false;for(const reminder of due){const key=`${reminder.id}:${reminder.dueDate}:${reminder.time||''}`;if(notified.includes(key))continue;await createReminderNotification(reminder);if('Notification'in window&&Notification.permission==='granted'){notified.push(key);changed=true}}if(changed)localStorage.setItem('pocket-ledger-notified-reminders',JSON.stringify(notified.slice(-250)));renderReminderBanner()}
  function reminderDueTimestamp(reminder){const time=reminder.time||'09:00';return new Date(`${reminder.dueDate}T${time}:00`).getTime()}
  function icsEscape(value){return String(value||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
  function downloadReminderCalendar(reminder){const date=reminder.dueDate.replaceAll('-',''),time=(reminder.time||'09:00').replace(':','')+'00',person=reminderPersonName(reminder),title=`${reminder.type==='receive'?T.toReceive:T.toGive} ${rupees(reminder.amount)} · ${person}`,lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Pocket Ledger//Offline Reminder//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',`UID:${reminder.id}@pocket-ledger`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${date}T${time}`,`SUMMARY:${icsEscape(title)}`,`DESCRIPTION:${icsEscape(reminder.note||T.udharReminder)}`];if(reminder.repeat==='Weekly')lines.push('RRULE:FREQ=WEEKLY');if(reminder.repeat==='Monthly')lines.push('RRULE:FREQ=MONTHLY');lines.push('BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY',`DESCRIPTION:${icsEscape(title)}`,'END:VALARM','END:VEVENT','END:VCALENDAR');const blob=new Blob([lines.join('\r\n')],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pocket-ledger-reminder-${reminder.id}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
  async function saveReminderForm(event){event.preventDefault();const error=$('#reminderFormError'),amount=Number($('#reminderAmount').value.replace(/,/g,'')),person=people.find(x=>x.id===$('#reminderPerson').value);error.textContent='';if(!person){error.textContent=T.reminderPersonRequired;return}if(!Number.isFinite(amount)||amount<=0){error.textContent=T.requiredAmount;return}if(!$('#reminderDueDate').value){error.textContent=T.dueDateRequired;return}const existing=reminders.find(x=>x.id===reminderEditId),value={id:reminderEditId||crypto.randomUUID(),type:$('#reminderType').value,person:{id:person.id,name:person.name},amount,dueDate:$('#reminderDueDate').value,time:$('#reminderTime').value,note:$('#reminderNote').value.trim(),repeat:$('#reminderRepeat').value,status:$('#reminderStatus').value,createdAt:existing?.createdAt||new Date().toISOString(),isDemo:!!existing?.isDemo};try{if(!existing&&value.status==='Pending')await requestReminderNotificationPermission();await LedgerDB.saveReminder(value);reminders=await LedgerDB.reminders();closeReminderForm();refresh();showToast(T.saved)}catch(err){error.textContent=T.reminderSaveFailed;console.error(err)}}
  async function addReminderPerson(){const name=prompt(T.enterPersonName)?.trim();if(!name)return;let person=people.find(x=>personKey(x.name)===personKey(name));if(!person){person={id:crypto.randomUUID(),name};await LedgerDB.savePerson(person);people=await LedgerDB.people()}fillReminderPeople(person.id)}
  async function exportBackup({silent=false,share=false,encrypted=false}={}){const [savedAccounts,savedTransactions,savedPeople,savedReminders,savedBudgets,savedRecurring,savedDrafts,savedInvestmentRecords]=await Promise.all([LedgerDB.accounts(),LedgerDB.transactions(),LedgerDB.people(),LedgerDB.reminders(),LedgerDB.budgets(),LedgerDB.recurring(),LedgerDB.recurringDrafts(),LedgerDB.investmentRecords()]);const data={app:'Pocket Ledger',version:6,exportedAt:new Date().toISOString(),accounts:savedAccounts,transactions:savedTransactions,people:savedPeople,reminders:savedReminders,budgets:savedBudgets,recurringEntries:savedRecurring,recurringDrafts:savedDrafts,investmentRecords:savedInvestmentRecords,categories,investments,settings:{language,theme:localStorage.getItem('pocket-ledger-theme')||'auto',lockDelay:localStorage.getItem('pocket-ledger-lock-delay')||'60000',dashboardMonth,lastBackupAt:localStorage.getItem('pocket-ledger-last-backup')||null,upiId:localStorage.getItem('pocket-ledger-upi-id')||'',upiName:localStorage.getItem('pocket-ledger-upi-name')||'',reminderLanguage:localStorage.getItem('pocket-ledger-reminder-language')||language,reminderTemplates:Object.fromEntries(['en','hi','gu'].map(key=>[key,localStorage.getItem(`pocket-ledger-reminder-template-${key}`)||''])),assistantEnabled:localStorage.getItem('pocket-ledger-assistant-enabled')==='1'}};let exportData=await PocketLedgerBackupCrypto.withChecksum(data);if(encrypted){const passphrase=prompt(T.backupPassphrasePrompt);if(!passphrase)return;if(passphrase.length<8){alert(T.backupPassphraseShort);return}if(passphrase!==prompt(T.backupPassphraseConfirm))return alert(T.backupPassphraseMismatch);try{exportData=await PocketLedgerBackupCrypto.encryptBackup(data,passphrase)}catch{alert(T.backupEncryptFailed);return}}const blob=new Blob([JSON.stringify(exportData,null,2)],{type:'application/json'}),filename=`pocket-ledger-${encrypted?'encrypted-':''}backup-${todayISO()}.json`;if(share&&navigator.share&&typeof File!=='undefined'){const file=new File([blob],filename,{type:'application/json'});try{if(!navigator.canShare||navigator.canShare({files:[file]})){await navigator.share({files:[file],title:T.backupExport});localStorage.setItem('pocket-ledger-last-backup',new Date().toISOString());if(!silent)showToast(T.backupDownloaded);renderBackupBanner();if(currentScreen==='settings')renderSettingsExtras();return}}catch(error){if(error.name==='AbortError')return}}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);localStorage.setItem('pocket-ledger-last-backup',new Date().toISOString());renderBackupBanner();if(!silent){showToast(T.backupDownloaded);if(currentScreen==='settings')renderSettingsExtras()}}
  function validateBackup(data){try{return PocketLedgerBackupValidation.validateBackup(data)}catch(error){throw new Error(error.message==='unsupported'?T.backupUnsupported:T.backupInvalid)}}
  async function readBackupFile(file){try{if(!file||file.size>50*1024*1024)throw new Error(T.backupInvalid);let data=JSON.parse(await file.text());if(data?.format==='pocket-ledger-encrypted'){const passphrase=prompt(T.backupImportPassphrase);if(!passphrase)return;data=await PocketLedgerBackupCrypto.decryptBackup(data,passphrase)}if(data?.checksum&&!await PocketLedgerBackupCrypto.verifyChecksum(data))throw new Error(T.backupChecksumFailed);pendingBackup=validateBackup(data);$('#restoreSummary').textContent=T.backupSummary.replace('{transactions}',pendingBackup.transactions.length).replace('{people}',pendingBackup.people.length).replace('{accounts}',pendingBackup.accounts.length).replace('{reminders}',pendingBackup.reminders.length);$('#restoreOverlay').hidden=false}catch(error){pendingBackup=null;alert(error.message||T.backupInvalid)}finally{$('#backupFileInput').value=''}}
  async function restoreBackup(mode){if(!pendingBackup)return;const data=pendingBackup;try{if(mode==='replace'){await exportBackup({silent:true});await LedgerDB.replaceAll(data);if(Array.isArray(data.categories))categories=data.categories;if(Array.isArray(data.investments))investments=data.investments;if(data.settings?.language&&window.TRANSLATIONS[data.settings.language]){language=data.settings.language;localStorage.setItem('pocket-ledger-language',language)}if(data.settings?.theme)applyTheme(data.settings.theme);if(data.settings?.lockDelay)localStorage.setItem('pocket-ledger-lock-delay',data.settings.lockDelay);if(data.settings?.dashboardMonth)dashboardMonth=data.settings.dashboardMonth}else{for(const [key,store,method] of [['transactions',data.transactions,'saveTransaction'],['people',data.people,'savePerson'],['accounts',data.accounts,'saveAccount'],['reminders',data.reminders,'saveReminder'],['budgets',data.budgets||[],'saveBudget'],['recurringEntries',data.recurringEntries||[],'saveRecurring'],['recurringDrafts',data.recurringDrafts||[],'saveRecurringDraft'],['investmentRecords',data.investmentRecords||[],'saveInvestmentRecord']]){const existing=new Set((await LedgerDB.all(store)).map(x=>x.id));for(const row of data[key]||[])if(!existing.has(row.id))await LedgerDB[method](row)}if(Array.isArray(data.categories))categories=[...new Set([...categories,...data.categories])];if(Array.isArray(data.investments))investments=[...new Set([...investments,...data.investments])]};localStorage.setItem('pocket-ledger-categories',JSON.stringify(categories));localStorage.setItem('pocket-ledger-investment-kinds',JSON.stringify(investments));localStorage.setItem('pocket-ledger-last-backup',new Date().toISOString());pendingBackup=null;$('#restoreOverlay').hidden=true;await reloadAppData();renderDataCheckStatus();T=window.TRANSLATIONS[language]||window.TRANSLATIONS.en;initLabels();showScreen(currentScreen);showToast(T.restoreComplete)}catch(error){alert(T.restoreFailed);console.error(error)}}
  function restoreOptionalSettings(settings={}){if(settings.upiId!==undefined)localStorage.setItem('pocket-ledger-upi-id',settings.upiId);if(settings.upiName!==undefined)localStorage.setItem('pocket-ledger-upi-name',settings.upiName);if(settings.reminderLanguage)localStorage.setItem('pocket-ledger-reminder-language',settings.reminderLanguage);for(const [key,value] of Object.entries(settings.reminderTemplates||{}))localStorage.setItem(`pocket-ledger-reminder-template-${key}`,value);if(settings.assistantEnabled!==undefined)localStorage.setItem('pocket-ledger-assistant-enabled',settings.assistantEnabled?'1':'0')}
  const restoreBackupWithSettings=restoreBackup;restoreBackup=async mode=>{const settings=pendingBackup?.settings;await restoreBackupWithSettings(mode);restoreOptionalSettings(settings||{});if(currentScreen==='settings')renderSettingsExtras()};
  async function reloadAppData(){[people,transactions,reminders]=await Promise.all([LedgerDB.people(),LedgerDB.transactions(),LedgerDB.reminders()]);accounts=await LedgerDB.accounts();await normalizePeople();await initializeAccountsAndMigrate();await loadPhase2Data();refresh()}
  async function deleteAllData(){if(!confirm(T.deleteAllConfirm))return;const typed=prompt(T.typeDelete);if(typed!=='DELETE')return alert(T.deleteAllCancelled);for(const store of ['transactions','people','accounts','reminders','budgets','recurring','recurringDrafts','investmentRecords'])await LedgerDB.clear(store);for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key?.startsWith('pocket-ledger-'))localStorage.removeItem(key)}transactions=[];people=[];reminders=[];accounts=[];budgets=[];recurringEntries=[];recurringDrafts=[];investmentLedgerEntries=[];categories=['Food','Travel','Fuel','Shopping','Bills','Rent','Medical','Education','Entertainment','Other'];investments=['SIP','Stocks','Gold','FD','Mutual Fund','Crypto','Other'];language='en';T=window.TRANSLATIONS.en;dashboardMonth=todayISO().slice(0,7);selectedAccountId='cash';applyTheme('auto');await LedgerDB.saveAccount({id:'cash',name:'Cash',kind:'cash',openingBalance:0});accounts=await LedgerDB.accounts();initLabels();refresh();showToast(T.allDataDeleted)}
  function renderDashboardRecent(){const rows=[...transactions].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||'')||String(b.id||'').localeCompare(String(a.id||''))).slice(0,5);$('#dashboardRecentEmpty').hidden=rows.length>0;$('#dashboardRecent').innerHTML=rows.map(x=>{const isLoss=x.type==='Investment Loss',tone=x.kind==='credit'?'positive':x.kind==='debit'||isLoss?'negative':'transfer-tone',sign=x.kind==='credit'?'+':x.kind==='debit'||isLoss?'-':'';return `<div class="dashboard-activity-row"><span class="dashboard-activity-icon ${x.kind}">${iconSvg(x.kind==='credit'?'credit':x.kind==='transfer'?'transfer':'debit')}</span><span><strong>${esc(x.type==='Transfer'?T.transfer:displayType(x.type))}${x.isDemo?` <small class="demo-entry-label">DEMO</small>`:''}</strong><small>${esc(dateLabel(x.date))}${x.person?.name?` · ${esc(x.person.name)}`:''}</small></span><strong class="${tone}">${sign}${rupees(x.amount)}</strong></div>`}).join('')}
  function renderInsights(list,metrics){const totals=new Map();list.filter(x=>x.type==='Daily Expense').forEach(x=>{const key=x.category||'Other';totals.set(key,(totals.get(key)||0)+Number(x.amount))});const highest=[...totals.entries()].sort((a,b)=>b[1]-a[1])[0];$('#highestExpenseInsight').textContent=highest?T.highestExpense.replace('{category}',categoryLabel(highest[0])).replace('{amount}',rupees(highest[1])):T.noDataThisMonth;const [y,m]=dashboardMonth.split('-').map(Number),now=new Date(),days=Number(y)===now.getFullYear()&&Number(m)===now.getMonth()+1?now.getDate():new Date(y,m,0).getDate();$('#averageExpenseInsight').textContent=T.averagePerDay.replace('{amount}',rupees(metrics.expense/Math.max(days,1)));$('#savingsRateInsight').textContent=T.savingsRate.replace('{percent}',metrics.income?Math.round(metrics.savings/metrics.income*100):0)}
  async function loadPhase2Data(){[budgets,recurringEntries,recurringDrafts,investmentLedgerEntries]=await Promise.all([LedgerDB.budgets(),LedgerDB.recurring(),LedgerDB.recurringDrafts(),LedgerDB.investmentRecords()]);const generated=PocketLedgerRecurring.buildDueDrafts(recurringEntries,recurringDrafts,transactions,todayISO());for(const draft of generated)await LedgerDB.saveRecurringDraft(draft);recurringDrafts=await LedgerDB.recurringDrafts()}
  function formatTemplate(key,params={}){let result=String(T[key]||key);for(const [name,value] of Object.entries(params))result=result.split('{'+name+'}').join(String(value));return result}
  function insightCopy(insight,key){const values={...insight.reasonParams};for(const name of ['average','amount','threshold','limit','due','budget'])if(values[name]!==undefined)values[name]=rupees(values[name]);if(values.category)values.category=categoryLabel(values.category);if(values.cadence)values.cadence=T[values.cadence]||values.cadence;if(values.direction)values.direction=T[values.direction]||values.direction;return formatTemplate(key==='title'?insight.titleKey:insight.reasonKey,values)}
  function dismissedInsightIds(){try{return JSON.parse(localStorage.getItem('pocket-ledger-dismissed-insights')||'[]')}catch{return []}}
  function renderSmartInsights(){const host=$('#smartInsightsList'),empty=$('#smartInsightsEmpty');if(!host||!empty)return;const data={transactions,people,accounts,reminders,budgets,lastBackupDate:localStorage.getItem('pocket-ledger-last-backup'),monthKey:dashboardMonth};const cards=PocketLedgerInsights.generateInsights(data,{monthKey:dashboardMonth,today:todayISO(),now:new Date()}).filter(card=>!dismissedInsightIds().includes(card.id));host.innerHTML='';empty.hidden=cards.length>0;for(const insight of cards){const card=document.createElement('article');card.className='smart-insight-card';const title=document.createElement('h3');title.textContent=insightCopy(insight,'title');const reason=document.createElement('p');reason.textContent=insightCopy(insight,'reason');const actions=document.createElement('div');actions.className='smart-insight-actions';const detail=document.createElement('button');detail.type='button';detail.className='text-link';detail.textContent=T.showDetails;detail.addEventListener('click',()=>showEntryDetails(insight.entryIds,title.textContent));actions.appendChild(detail);const why=document.createElement('details');why.className='insight-why';const summary=document.createElement('summary');summary.textContent=T.whySeeingThis;const explanation=document.createElement('p');explanation.textContent=reason.textContent;why.append(summary,explanation);actions.appendChild(why);if(insight.action?.cadence){const create=document.createElement('button');create.type='button';create.className='secondary-button';create.textContent=T.createRecurringEntry;create.addEventListener('click',()=>prepareRecurringFromInsight(insight));actions.appendChild(create)}if(insight.action?.screen==='settings'){const settings=document.createElement('button');settings.type='button';settings.className='secondary-button';settings.textContent=T.settings;settings.addEventListener('click',()=>showScreen('settings'));actions.appendChild(settings)}const dismiss=document.createElement('button');dismiss.type='button';dismiss.className='text-link';dismiss.textContent=T.dismissInsight;dismiss.addEventListener('click',()=>{const ids=dismissedInsightIds();ids.push(insight.id);localStorage.setItem('pocket-ledger-dismissed-insights',JSON.stringify([...new Set(ids)]));renderSmartInsights()});actions.appendChild(dismiss);card.append(title,reason,actions);host.appendChild(card)}}
  function showEntryDetails(ids,title){entryDetailsIds=[...new Set(ids||[])];showScreen('entry');$('#entryInsightTitle').textContent=title||T.insightDetailsTitle;renderEntryInsightDetails();$('#entryInsightDetails').scrollIntoView({behavior:'smooth',block:'start'})}
  function renderEntryInsightDetails(){const section=$('#entryInsightDetails'),host=$('#entryInsightRows');if(!section||!host)return;section.hidden=!entryDetailsIds;host.innerHTML='';if(!entryDetailsIds)return;const rows=transactions.filter(row=>entryDetailsIds.includes(row.id)).sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));if(!rows.length){host.textContent=T.noInsightEntries;return}for(const row of rows){const item=document.createElement('article');item.className='insight-entry-row';const main=document.createElement('span');main.textContent=[displayType(row.type),dateLabel(row.date),row.category||row.person?.name||row.note].filter(Boolean).join(' · ');const amountNode=document.createElement('strong');amountNode.textContent=(row.kind==='credit'?'+':row.kind==='debit'?'-':'')+rupees(row.amount);amountNode.className=row.kind==='credit'?'positive':'negative';item.append(main,amountNode);host.appendChild(item)}}
  function renderSmartDashboard(){renderSmartInsights();renderSafeSpendForecast();renderBudgetsDashboard()}
  function renderSafeSpendForecast(){const safe=PocketLedgerForecast.safeToSpend({balance:allTimeBalance(),reminders,recurringDrafts,recurringEntries,budgets,transactions,monthKey:dashboardMonth,today:todayISO()});$('#safeToSpendValue').textContent=signedRupees(safe.daily);$('#safeToSpendValue').classList.toggle('negative',safe.daily<0);$('#safeToSpendFormula').textContent=formatTemplate('safeSpendFormula',{balance:rupees(safe.balance),commitments:rupees(safe.committed),reserved:rupees(safe.reserved),days:safe.daysLeft});$('#safeSpendExplain').textContent=T.safeSpendTooltip;$('#safeSpendWhy').title=T.safeSpendTooltip;const forecast=PocketLedgerForecast.monthEndForecast({balance:allTimeBalance(),transactions,reminders,recurringEntries,recurringDrafts,monthKey:dashboardMonth,today:todayISO()});$('#forecastText').textContent=formatTemplate('forecastAtPace',{amount:rupees(forecast.forecast)})+' '+formatTemplate('forecastBand',{low:rupees(forecast.low),high:rupees(forecast.high)});$('#forecastExplanation').textContent=T.forecastReason;const start=allTimeBalance(),end=forecast.forecast,low=forecast.low,high=forecast.high,y=value=>110-(value-Math.min(start,low,end))/(Math.max(start,high,end)-Math.min(start,low,end)||1)*80;$('#forecastChart').innerHTML='<svg viewBox="0 0 360 130" role="img" aria-label="'+esc(T.monthEndForecast)+'"><path d="M20 112H340" stroke="var(--line)"/><path d="M30 '+y(start)+' L330 '+y(high)+' L330 '+y(low)+' Z" fill="var(--blue-soft)" stroke="none"/><path d="M30 '+y(start)+' L330 '+y(end)+'" fill="none" stroke="var(--blue)" stroke-width="3"/><circle cx="30" cy="'+y(start)+'" r="4" fill="var(--green)"/><circle cx="330" cy="'+y(end)+'" r="4" fill="var(--blue)"/><text x="30" y="127" fill="var(--muted)" font-size="10">'+esc(T.today)+'</text><text x="330" y="127" text-anchor="end" fill="var(--muted)" font-size="10">'+esc(T.monthEndForecast)+'</text></svg>'}
  function renderBudgetsDashboard(){const host=$('#dashboardBudgetList');if(!host)return;host.innerHTML='';const rows=PocketLedgerBudgets.listBudgetUsage(budgets,transactions,dashboardMonth);for(const budget of rows){const item=document.createElement('div');item.className='budget-dashboard-row '+budget.state;const label=document.createElement('span');label.textContent=budget.scope==='overall'?T.overallBudget:categoryLabel(budget.category);const value=document.createElement('strong');value.textContent=rupees(budget.spent)+' / '+rupees(budget.limit);item.append(label,value);host.appendChild(item)}}
  function renderBudgetScreen(){const monthText=$('#budgetMonthText');if(monthText)monthText.textContent=$('#dashboardMonthLabel').textContent;const selector=$('#budgetCategory'),previous=selector.value;selector.innerHTML='';for(const [value,label] of [['Overall',T.overallBudget],...categories.map(category=>[category,categoryLabel(category)])]){const option=document.createElement('option');option.value=value;option.textContent=label;selector.appendChild(option)}if([...selector.options].some(option=>option.value===previous))selector.value=previous;const list=$('#budgetList');list.innerHTML='';const usages=PocketLedgerBudgets.listBudgetUsage(budgets,transactions,dashboardMonth);$('#budgetEmpty').hidden=usages.length>0;for(const budget of usages){const article=document.createElement('article');article.className='budget-card '+budget.state;const heading=document.createElement('div');heading.className='section-title-row';const name=document.createElement('strong');name.textContent=budget.scope==='overall'?T.overallBudget:categoryLabel(budget.category);const total=document.createElement('span');total.textContent=rupees(budget.spent)+' / '+rupees(budget.limit);heading.append(name,total);const track=document.createElement('div');track.className='budget-progress-track';track.setAttribute('role','progressbar');track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax','100');track.setAttribute('aria-valuenow',String(Math.min(100,budget.percent)));track.setAttribute('aria-label',name.textContent);const fill=document.createElement('i');fill.style.width=Math.max(0,Math.min(100,budget.percent))+'%';track.appendChild(fill);const meta=document.createElement('p');meta.textContent=(budget.percent>=100?T.progressOver:budget.percent>=80?T.progressNear:T.progressUnder)+' · '+rupees(budget.remaining);const controls=document.createElement('div');controls.className='budget-actions';const edit=document.createElement('button');edit.type='button';edit.className='secondary-button';edit.textContent=T.edit;edit.addEventListener('click',()=>{budgetEditId=budget.id;$('#budgetCategory').value=budget.category;$('#budgetAmount').value=budget.amount;$('#budgetForm').scrollIntoView({behavior:'smooth'})});const remove=document.createElement('button');remove.type='button';remove.className='secondary-button';remove.textContent=T.delete;remove.addEventListener('click',()=>deleteBudget(budget.id));controls.append(edit,remove);article.append(heading,track,meta,controls);list.appendChild(article)}}
