  function confirmQuickAdd(){const type=$('#qPreviewType').value,targetKind=['Salary','Side Income','Udhar Taken','Udhar Received Back','Investment Profit'].includes(type)?'credit':'debit',personId=$('#qPreviewPerson').value,person=people.find(p=>p.id===personId),amount=Number($('#qPreviewAmount').value.replace(/,/g,''));if(!amount||amount<=0){$('#qPreviewAmount').focus();return}if(udharTypes.includes(type)&&!person){$('#qPreviewPerson').focus();return}const previewCategory=$('#qPreviewCategory')?.value||quickParsed?.category||'Other';selectedAccountId=$('#qPreviewAccount').value||selectedAccountId;setKind(targetKind);selectedType=type;renderTypeChips();const typeChip=$(`#typeChips .chip[data-type="${CSS.escape(type)}"]`);typeChip?.classList.add('selected');$('#amount').value=formatMoney(amount);$('#date').value=$('#qPreviewDate').value||todayISO();$('#note').value=$('#qPreviewNote').value;renderDynamicFields();const accountChip=$(`[data-chip-group="account"] .chip[data-value="${CSS.escape(selectedAccountId)}"]`);accountChip?.click();if(type==='Daily Expense')selectValue('category',previewCategory);if(person)choosePerson(person);if($('#investmentName'))$('#investmentName').value=$('#qPreviewInvestment')?.value||quickParsed?.investmentName||'';if($('#sourceName')&&type==='Salary')$('#sourceName').value='';$('#quickAddPreview').hidden=true;quickParsed=null;form.requestSubmit()}
  function accountById(id){return accounts.find(a=>a.id===id)}
  function accountHistoryError(result){if(result.ok)return '';return T.historyWouldGoNegative.replace('{account}',result.account.name).replace('{date}',result.date?dateLabel(result.date,{day:'numeric',month:'short',year:'numeric'}):T.openingBalance).replace('{amount}',rupees(result.shortfall))}
  function currentValidationError(){const amount=Number($('#amount').value.replace(/,/g,''));if(!(amount>0)||kind==='credit'||selectedType==='Investment Loss')return '';const id=kind==='transfer'?$('#transferFrom')?.value:selectedChip('account'),account=accountById(id);if(!account)return '';const baseline=editId?transactions.filter(row=>row.id!==editId):transactions,available=Math.max(0,window.PocketLedgerAccountBalances.balance(account,baseline));return amount>available?T.insufficientBalance.replace('{account}',account.name).replace('{amount}',rupees(available)):''}
  function updateAccountAvailability(){const message=currentValidationError(),error=$('#availabilityError');if(error)error.textContent=message;const save=$('#saveButton');if(save)save.disabled=Boolean(message)||saveLock}
  function accountImpactPreview(){const id=$('#accountEditorId').value,account=accountById(id),input=$('#accountEditorOpening'),preview=$('#accountCurrentPreview'),impact=$('#accountOpeningImpact');if(!preview||!input)return;const raw=input.value.replace(/,/g,''),opening=Number(raw);if(!Number.isFinite(opening)||opening<0){preview.textContent='';impact.hidden=true;return}const current=account?accountBalance(account.id):opening,after=account?current+opening-(Number(account.openingBalance)||0):opening;preview.textContent=T.accountCurrentPreview.replace('{amount}',rupees(after));if(account&&opening!==(Number(account.openingBalance)||0)){impact.textContent=T.openingBalanceImpact.replace('{before}',rupees(current)).replace('{after}',rupees(after));impact.hidden=false}else impact.hidden=true}
  function openAccountEditor(id=''){const account=accountById(id);$('#accountEditorForm').reset();$('#accountEditorId').value=account?.id||'';$('#accountEditorTitle').textContent=account?T.accountEdit:T.addAccount;$('#accountEditorKind').value=account?.kind||'bank';$('#accountEditorKind').disabled=account?.kind==='cash';$('#accountEditorName').value=account?.name||'';$('#accountEditorName').disabled=account?.kind==='cash';$('#accountEditorNickname').value=account?.nickname||'';$('#accountEditorLast4').value=account?.last4||'';$('#accountEditorIcon').value=account?.icon||(account?.kind==='cash'?'▣':'⌂');$('#accountEditorColor').value=/^#[0-9a-f]{6}$/i.test(account?.color||'')?account.color:'#4c8bf5';$('#accountEditorOpening').value=formatMoney(account?.openingBalance||0);$('#accountEditorError').textContent='';$('#accountNameError').textContent='';$('#accountOpeningError').textContent='';accountImpactPreview();$('#accountEditorDialog').showModal();$('#accountEditorName').focus()}
  function closeAccountEditor(){$('#accountEditorDialog').close()}
  async function saveAccountEditor(event){event.preventDefault();const id=$('#accountEditorId').value,old=accountById(id),name=$('#accountEditorName').value.trim(),opening=Number($('#accountEditorOpening').value.replace(/,/g,'')),nameError=$('#accountNameError'),openingError=$('#accountOpeningError'),error=$('#accountEditorError');nameError.textContent='';openingError.textContent='';error.textContent='';if(!name){nameError.textContent=T.accountNameRequired;return}if(accounts.some(a=>a.id!==id&&a.name.trim().toLowerCase()===name.toLowerCase())){nameError.textContent=T.accountDuplicate;return}if(!old&&$('#accountEditorKind').value==='cash'&&accounts.some(a=>a.kind==='cash'||a.id==='cash')){nameError.textContent=T.cashAccountExists;return}if(!Number.isFinite(opening)||opening<0){openingError.textContent=T.negativeOpeningBalance;return}const current=old?accountBalance(id):0,after=old?current+opening-(Number(old.openingBalance)||0):opening;if(old&&opening!==(Number(old.openingBalance)||0)&&!confirm(T.openingImpactConfirm.replace('{before}',rupees(current)).replace('{after}',rupees(after))))return;const value={...(old||{}),id:id||crypto.randomUUID(),name:old?.kind==='cash'?old.name:name,kind:old?.kind==='cash'?'cash':$('#accountEditorKind').value,openingBalance:opening,nickname:$('#accountEditorNickname').value.trim(),last4:$('#accountEditorLast4').value.replace(/\D/g,'').slice(0,4),icon:$('#accountEditorIcon').value,color:$('#accountEditorColor').value,archived:old?.archived||false,sortOrder:old?.sortOrder??accounts.length};const checked=window.PocketLedgerAccountBalances.validateChange(accounts,transactions,{accountUpdates:old?{[id]:{openingBalance:opening}}:{}});if(!checked.ok){error.textContent=accountHistoryError(checked);return}await LedgerDB.saveAccount(value);accounts=await LedgerDB.accounts();closeAccountEditor();refreshAccountFields();renderAccountManager();refresh();showToast(old?T.accountUpdated:T.accountAdded)}
  async function toggleArchiveAccount(id){const account=accountById(id);if(!account||account.kind==='cash')return;account.archived=!account.archived;await LedgerDB.saveAccount(account);accounts=await LedgerDB.accounts();if(account.archived&&selectedAccountId===id)selectedAccountId='cash';refreshAccountFields();refresh();showToast(T.accountArchivedDone)}
  async function moveAccount(id,direction){const list=orderedAccounts(true),index=list.findIndex(a=>a.id===id),other=list[index+(direction==='up'?-1:1)];if(!other)return;const first=Number(list[index].sortOrder)||index,second=Number(other.sortOrder)||index+(direction==='up'?-1:1);list[index].sortOrder=second;other.sortOrder=first;await Promise.all([LedgerDB.saveAccount(list[index]),LedgerDB.saveAccount(other)]);accounts=await LedgerDB.accounts();refreshAccountFields();renderAccountManager()}
  function openDataCheckEntry(id){const row=transactions.find(x=>x.id===id);if(!row)return;showScreen('entry');editTransaction(id)}
  async function addAccount(){openAccountEditor()}
  async function renameAccount(id){openAccountEditor(id)}
  function accountHasReferences(accountId){return PocketLedgerReferences.accountHasReferences(accountId,transactions,recurringEntries,recurringDrafts)}
  async function deleteAccount(id){const account=accounts.find(a=>a.id===id);if(!account)return;if(account.kind==='cash')return;if(accountHasReferences(id)){alert(T.accountDeleteRule);return}if(!confirm(T.deleteAccountConfirm))return;await LedgerDB.deleteAccount(id);accounts=await LedgerDB.accounts();if(selectedAccountId===id)selectedAccountId='cash';refreshAccountFields();renderAccountManager();refresh()}  async function onReminderForeground(){try{reminders=await LedgerDB.reminders();renderReminderBanner();if(currentScreen==='reminders')renderReminderScreen();else if(currentScreen==='dashboard')renderDashboardReminders();await checkDueReminders()}catch(error){console.error(error)}}
  document.addEventListener('visibilitychange',()=>{if(document.hidden)backgroundSince=Date.now();else{const delay=Number(localStorage.getItem('pocket-ledger-lock-delay')??60000);if(readPinRecord()&&backgroundSince&&Date.now()-backgroundSince>=delay)showPinLock();backgroundSince=0;onReminderForeground()}});window.addEventListener('focus',()=>{if(readPinRecord()&&backgroundSince){const delay=Number(localStorage.getItem('pocket-ledger-lock-delay')??60000);if(Date.now()-backgroundSince>=delay)showPinLock()}onReminderForeground()});setInterval(()=>{if(!document.hidden)checkDueReminders()},60000);
  $('#reloadAfterStorageError').addEventListener('click',()=>location.reload());
  async function start(){try{loadAppSettings();initLabels();renderPinKeypad();[people,transactions,reminders]=await Promise.all([LedgerDB.people(),LedgerDB.transactions(),LedgerDB.reminders()]);await normalizePeople();await initializeAccountsAndMigrate();await loadPhase2Data()}catch(e){console.error(e);document.body.classList.add('storage-failed');$('#storageFailure').hidden=false;return}selectedAccountId=accounts.find(a=>a.id==='cash'||a.kind==='cash')?.id||'cash';setKind('debit');selectedType='Daily Expense';renderTypeChips();renderDynamicFields();refresh();showScreen('entry');renderBackupBanner();if(readPinRecord())showPinLock();if(!localStorage.getItem('pocket-ledger-onboarded')&&transactions.length===0&&people.length===0)openTour();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').then(()=>onReminderForeground()).catch(()=>onReminderForeground());else onReminderForeground()}
  start();
